// Telas do Guia de Treino
window.VIEWS={}; window.AFTER={};
const V=window.VIEWS, A=window.AFTER;
const DIAS={seg:"Seg",ter:"Ter",qua:"Qua",qui:"Qui",sex:"Sex",sab:"Sáb",dom:"Dom"};
function setTitle(t){ document.getElementById('topTitle').textContent=t; }

// ================= HOJE =================
V.hoje=()=>{ setTitle("Hoje"); const pl=planoHoje(); const p=programa(); const nome=S.perfil.nome?`, ${S.perfil.nome.split(' ')[0]}`:"";
  const lastCk=S.checkins[S.checkins.length-1]; const vol=volumeSemana(); const sessSem=S.logs.filter(l=>l.data>=semanaIni()).length; const bjjSem=S.bjj.filter(l=>l.data>=semanaIni()).length; const cardSem=S.cardio.filter(l=>l.data>=semanaIni()).reduce((a,c)=>a+(c.min||0),0);
  const dias=Object.keys(DIAS).map(d=>{const s=window.PROGRAMS.ppl2.semana[d]; return `<div class="day ${d===pl.dia?'today':''}"><b>${DIAS[d]}</b>${s.bjj?`<span class="tag bjj">${s.bjj==="opcional"?"BJJ?":"BJJ"}</span>`:""}${s.musc?`<span class="tag ${s.musc==='rotação'?'':s.musc}">${s.musc==='rotação'?'PPL':s.musc.toUpperCase()}</span>`:""}</div>`;}).join("");
  const alvoTot=Object.values(ALVO).reduce((a,[x,y])=>a+y,0); const volTot=Object.entries(ALVO).reduce((a,[g])=>a+Math.min(vol[g]||0,ALVO[g][1]),0); const pct=Math.round(volTot/alvoTot*100);
  return `
  <div class="eyebrow">${DIAS[pl.dia]} · ${fmtDL(today())}</div>
  <h1>${pl.sessao?esc(pl.sessao.nome):(pl.dia==="dom"?"Descanso":"Tatame")}${nome?`<br><span class="em" style="font-size:.6em">${esc(nome.replace(', ',''))}</span>`:""}</h1>
  <p class="muted small">${p.nome}</p>
  <div class="card hero">
    <div class="row" style="align-items:center"><svg class="ring" viewBox="0 0 80 80"><circle class="t" cx="40" cy="40" r="35"/><circle class="v" id="ringVol" cx="40" cy="40" r="35" data-pct="${pct}"/></svg><div style="flex:1"><div class="eyebrow" style="color:var(--tx2)">Dose da semana</div><div class="big count" data-to="${pct}">0</div><div class="tiny">% do volume-alvo · ${sessSem} musc · ${bjjSem} BJJ · ${cardSem} min cardio</div></div></div>
    <div class="row" style="margin-top:10px">${pl.bjj?`<span class="chip warn">BJJ ${pl.bjj==="opcional"?"opcional":"fixo"}</span>`:"<span></span>"}</div>
    ${pl.sessao?`<p class="muted small" style="margin-top:6px">${pl.sessao.slots.length} exercícios · ${pl.sessao.slots.reduce((a,s)=>a+s.sets,0)} séries · ${pl.sessao.cardio||""}</p>
      <div style="margin-top:12px" class="col"><button class="btn em" onclick="go('sessao',{s:'${pl.musc}'})">Iniciar ${esc(pl.sessao.nome)}</button>
      <button class="btn sec" onclick="sheet(V._trocar())">Outra sessão ou pular</button></div>`
      :`<p class="serif" style="margin-top:8px">${pl.dia==="dom"?"Recuperação <i>é</i> treino. Sono, comida, passos leves.":"Hoje é tatame. O próximo da rotação é "+p.sessoes[pl.musc||proximaSessaoId()].nome+"."}</p>
      <div style="margin-top:12px" class="col"><button class="btn sec" onclick="go('sessao',{s:'${proximaSessaoId()}'})">Treinar mesmo assim (${esc(p.sessoes[proximaSessaoId()].nome)})</button></div>`}
    ${pl.nota?`<p class="tiny" style="margin-top:10px">${esc(pl.nota)}</p>`:""}
  </div>
  <div class="grid2">
    <button class="btn sec" onclick="sheet(V._logBjj())">🥋 Registrar BJJ</button>
    <button class="btn sec" onclick="sheet(V._logCardio())">❤️ Registrar cardio</button>
  </div>
  <div class="grid2" style="margin-top:8px"><button class="btn ghost" onclick="go('nutricao')">◐ Diário de hoje</button><button class="btn ghost" onclick="go('calendario')">▦ Calendário</button></div>
  <h3>Semana</h3>
  <div class="grid3" style="grid-template-columns:repeat(7,1fr);gap:4px">${dias}</div>
  <div class="grid3" style="margin-top:10px">
    <div class="kpi"><div class="v">${sessSem}</div><div class="l">musculações</div></div>
    <div class="kpi"><div class="v">${bjjSem}</div><div class="l">BJJ</div></div>
    <div class="kpi"><div class="v">${cardSem}<span class="small muted"> min</span></div><div class="l">cardio</div></div>
  </div>
  <h3>Volume da semana <span class="tiny">(diretas + 0,5 indiretas)</span></h3>
  <div class="card">${["Dorsal","Ombro","Peitoral","Quadríceps","Posterior","Glúteo","Tríceps","Bíceps"].map(g=>volBar(g,vol[g]||0)).join("")}</div>
  ${lastCk?`<h3>Último check-in · ${fmtD(lastCk.data)}</h3><div class="grid3"><div class="kpi"><div class="v">${lastCk.peso??"—"}</div><div class="l">kg</div></div><div class="kpi"><div class="v">${lastCk.cintura??"—"}</div><div class="l">cintura cm</div></div><div class="kpi"><div class="v">${lastCk.sono??"—"}</div><div class="l">sono h</div></div></div>`
   :`<div class="card sub"><b>Sem check-in ainda.</b><p class="muted small">Peso médio de 7 dias, cintura e sono, uma vez por semana. É isso que decide ajuste, não o peso de um dia.</p><button class="btn sm sec" onclick="go('progresso',{t:'checkin'})">Fazer check-in</button></div>`}
  ${S.perfil.cotovelo?`<div class="alert" style="margin-top:12px">Cotovelo sintomático: toalha, rosca martelo, dead hang, farmer carry pesado e sled pull ficam fora. Desliga em Mais → Perfil quando o quadro mudar.</div>`:""}`; };
A.hoje=()=>{ const r=document.getElementById('ringVol'); if(r){ const pct=+r.dataset.pct; requestAnimationFrame(()=>requestAnimationFrame(()=>{ r.style.strokeDashoffset=220-220*Math.min(100,pct)/100; })); }
  document.querySelectorAll('.count').forEach(el=>{ const to=+el.dataset.to; const t0=performance.now(); (function f(t){ const p=Math.min(1,(t-t0)/1200); const e=1-Math.pow(1-p,3); el.textContent=Math.round(to*e); if(p<1) requestAnimationFrame(f); })(t0); });
  document.querySelectorAll('.bar i[data-w]').forEach((i,k)=>setTimeout(()=>{ i.style.width=i.dataset.w+'%'; },60*k+30)); };
function semanaIni(){ const x=new Date(); x.setDate(x.getDate()-((x.getDay()+6)%7)); return x.toISOString().slice(0,10); }
function volBar(g,v){ const [a,b]=ALVO[g]||[0,0]; const pct=Math.min(100,v/(b||1)*100); const cls=v>=a&&v<=b?'ok':v>b?'over':''; return `<div class="row" style="margin:6px 0"><span class="small" style="width:90px">${g}</span><div class="bar" style="flex:1"><i class="${cls}" data-w="${pct}"></i></div><span class="small mono" style="width:70px;text-align:right">${Math.round(v*10)/10} / ${a}–${b}</span></div>`; }
V._trocar=()=>{ const p=programa(); return `<h2>Escolher sessão</h2><div class="list">${p.rotacao.map(k=>`<div class="item" onclick="closeSheet();go('sessao',{s:'${k}'})"><div class="n" style="background:${p.sessoes[k].cor}">${p.sessoes[k].nome[0]}</div><div class="t"><b>${esc(p.sessoes[k].nome)}</b><span>${p.sessoes[k].slots.length} exercícios</span></div><span class="arrow">›</span></div>`).join("")}</div><div class="sep"></div><button class="btn ghost" onclick="avancaRotacao();closeSheet();route();toast('Rotação avançada')">Pular a sessão de hoje (avança a rotação)</button>`; };
V._logBjj=()=>`<h2>Registrar BJJ</h2><label>Data</label><input id="bjData" type="date" value="${today()}"><label>Tipo</label><select id="bjTipo"><option value="gi">Kimono (Gi)</option><option value="nogi">No-Gi</option><option value="openmat">Open mat</option><option value="tecnico">Só técnica</option></select><div class="grid2"><div><label>Duração (min)</label><input id="bjMin" type="number" value="75"></div><div><label>Intensidade (RPE 1–10)</label><input id="bjRpe" type="number" value="7"></div></div><div class="grid2"><div><label>Dor cotovelo (0–10)</label><input id="bjCot" type="number" value="0"></div><div><label>Dor joelho (0–10)</label><input id="bjJo" type="number" value="0"></div></div><label>Notas (técnica, posições)</label><input id="bjNotas" placeholder="Meia-guarda, knee cut…"><div style="margin-top:14px"><button class="btn" onclick="salvaBjj()">Salvar</button></div>`;
window.salvaBjj=()=>{ S.bjj.push({id:uid(),data:bjData.value,tipo:bjTipo.value,min:num(bjMin.value),rpe:num(bjRpe.value),dorCot:num(bjCot.value),dorJo:num(bjJo.value),notas:bjNotas.value}); S.bjj.sort((a,b)=>a.data.localeCompare(b.data)); save(); closeSheet(); toast("BJJ registrado"); route(); };
V._logCardio=(tipoPre)=>`<h2>Registrar cardio / esporte</h2><label>Data</label><input id="cdData" type="date" value="${today()}"><label>Tipo</label><select id="cdTipo">${["Z2 base","Caminhada","Esteira intervalado","Corrida","Hyrox leve","Hyrox simulação","Boxe","Futebol","Natação","Bike","Passos do dia"].map(t=>`<option ${t===tipoPre?'selected':''}>${t}</option>`).join("")}</select><div class="grid2"><div><label>Minutos</label><input id="cdMin" type="number" value="30"></div><div><label>FC média (opcional)</label><input id="cdFc" type="number"></div></div><div class="grid2"><div><label>Distância km (opcional)</label><input id="cdDist" type="number" step="0.1"></div><div><label>RPE 1–10</label><input id="cdRpe" type="number" value="4"></div></div><label>Notas</label><input id="cdNotas"><div style="margin-top:14px"><button class="btn" onclick="salvaCardio()">Salvar</button></div>`;
window.salvaCardio=()=>{ S.cardio.push({id:uid(),data:cdData.value,tipo:cdTipo.value,min:num(cdMin.value),fc:num(cdFc.value),dist:num(cdDist.value),rpe:num(cdRpe.value),notas:cdNotas.value}); S.cardio.sort((a,b)=>a.data.localeCompare(b.data)); save(); closeSheet(); toast("Registrado"); route(); };

// ================= TREINO (programa) =================
V.treino=(p)=>{ setTitle("Treino"); const pr=programa(); const tab=p.t||"sessoes";
  const segs=`<div class="seg">${[["sessoes","Sessões"],["bib","Biblioteca"],["regras","Regras"]].map(([k,n])=>`<button class="${tab===k?'on':''}" onclick="go('treino',{t:'${k}'})">${n}</button>`).join("")}</div>`;
  if(tab==="bib") return `<h1>Biblioteca</h1>${segs}${V._bib(p)}`;
  if(tab==="regras") return `<h1>Regras do programa</h1>${segs}<div class="card"><b>${esc(pr.nome)}</b><p class="tiny">${esc(pr.origem)}</p><ul class="small">${pr.principios.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>${pr.regras?`<div class="card"><b>Semana com BJJ</b><ul class="small">${pr.regras.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>`:""}${pr.volumeAlvo?`<div class="card"><b>Volume-alvo por grupo (séries/semana)</b><div class="tablewrap"><table><tr><th>Grupo</th><th class="num">Alvo</th></tr>${Object.entries(pr.volumeAlvo).map(([g,v])=>`<tr><td>${g}</td><td class="num">${v}</td></tr>`).join("")}</table></div></div>`:""}
    <div class="card"><b>Progressão</b><p class="small">Compostos: fez o topo da faixa nas working sets com técnica → sobe carga. 6/6 → mantém. ≤5 → ajusta para baixo. Isoladores: topo em todas as séries → menor incremento. Toda semana pelo menos um: +1 rep, +carga, mesma carga com técnica melhor ou mesma performance com menos fadiga.</p></div>
    <div class="card"><b>Deload</b><p class="small">A cada 4–6 semanas ou antes se aparecerem 2 sessões seguidas de queda, dor articular subindo, sono ruim ou 5–6 BJJ na semana: volume −40–50%, carga −10–15%, RIR 3–4, cardio mantém ou cai leve.</p></div>`;
  return `<h1>${esc(pr.nome)}</h1>${segs}
  <div class="row wrap" style="margin:6px 0 10px"><span class="chip ${S.perfil.programa==='ppl2'?'on':''}" onclick="S.perfil.programa='ppl2';save();route()">PPL 2.0</span><span class="chip ${S.perfil.programa==='predio'?'on':''}" onclick="S.perfil.programa='predio';save();route()">Prédio A/B</span>${S.gerado?`<span class="chip ${S.perfil.programa==='gerado'?'on':''}" onclick="S.perfil.programa='gerado';save();route()">Gerado</span>`:''}<span class="chip" style="border:1px dashed var(--line)" onclick="go('gerador')">✦ Montar programa</span><span class="chip" onclick="go('esportes')">◎ Esportes</span><span class="tiny">próxima da rotação: <b>${esc(pr.sessoes[proximaSessaoId()].nome)}</b></span></div>
  <div class="list">${pr.rotacao.map(k=>{const s=pr.sessoes[k]; return `<div class="item" onclick="go('sessao',{s:'${k}'})"><div class="n" style="background:${s.cor};color:#fff">${s.nome[0]}</div><div class="t"><b>${esc(s.nome)}</b><span>${s.slots.map(x=>resolveEx(x.ex).nome.split(' ')[0]).slice(0,5).join(" · ")}…</span></div><span class="arrow">›</span></div>`;}).join("")}</div>
  <h3>Modo de equipamento</h3><div class="row wrap">${Object.entries(MODOS).map(([k,n])=>`<span class="chip ${S.perfil.modo===k?'on':''}" onclick="S.perfil.modo='${k}';save();route()">${n}</span>`).join("")}</div><p class="tiny">Trocar o modo troca cada exercício pelo substituto equivalente, mantendo séries, faixas e RIR.</p>`; };
V._bib=(p)=>{ const q=(p.q||"").toLowerCase(); const grupos=[...new Set(window.EXERCISES.map(e=>e.grupo))]; const g=p.g||""; const lista=window.EXERCISES.filter(e=>(!g||e.grupo===g)&&(!q||(e.nome+e.sub).toLowerCase().includes(q)));
  return `<input placeholder="Buscar exercício…" value="${esc(p.q||"")}" oninput="go('treino',{t:'bib',g:'${g}',q:this.value})" style="margin:8px 0"><div class="row wrap"><span class="chip ${!g?'on':''}" onclick="go('treino',{t:'bib'})">Todos</span>${grupos.map(x=>`<span class="chip ${g===x?'on':''}" onclick="go('treino',{t:'bib',g:'${x}'})">${x}</span>`).join("")}</div>
  <div class="list" style="margin-top:10px">${lista.map(e=>`<div class="item" onclick="go('exercicio',{id:'${e.id}'})"><div class="n">${e.video?"▶":"≡"}</div><div class="t"><b>${esc(e.nome)}</b><span>${esc(e.sub)}</span></div>${suspenso(e)?'<span class="chip warn">suspenso</span>':''}<span class="arrow">›</span></div>`).join("")}</div>`; };

// ================= SESSÃO GUIADA =================
V.sessao=(p)=>{ const pr=programa(); const s=pr.sessoes[p.s]; if(!s) return V.treino({}); setTitle(s.nome);
  const draft=S._draft&&S._draft.sessao===p.s&&S._draft.programa===pr.id?S._draft:null;
  const slots=s.slots.map((sl,i)=>{ const e=resolveEx(sl.ex); const sug=sugestaoCarga(e.id,sl.reps); const fl=flagsAtivas(e); const susp=suspenso(e);
    const sets=Array.from({length:sl.sets},(_,k)=>{ const d=draft?draft.sets.find(x=>x.ex===e.id&&x.set===k):null; return `<div class="set-row"><span class="muted small mono">${k+1}</span><input type="number" step="0.5" placeholder="kg" value="${d?.peso??(sug?.peso??"")}" data-ex="${e.id}" data-set="${k}" data-f="peso"><input type="number" placeholder="reps" value="${d?.reps??""}" data-ex="${e.id}" data-set="${k}" data-f="reps"><input type="number" placeholder="RIR" value="${d?.rir??""}" data-ex="${e.id}" data-set="${k}" data-f="rir"><button class="ck ${d?.done?'done':''}" data-ex="${e.id}" data-set="${k}" onclick="toggleSet(this,'${sl.rest||'90 s'}')">✓</button></div>`; }).join("");
    return `<div class="card" id="ex_${e.id}"><div class="row"><div><b>${i+1}. ${esc(e.nome)}</b><div class="tiny">${esc(e.sub)}</div></div><button class="btn sm ghost" onclick="go('exercicio',{id:'${e.id}',back:'sessao',s:'${p.s}'})">Ficha</button></div>
      <div class="row wrap" style="margin:8px 0 4px"><span class="pill">${sl.sets} × ${sl.reps}</span><span class="pill">RIR ${sl.rir||"—"}</span><span class="pill">⏱ ${sl.rest||"90 s"}</span>${sl.nota?`<span class="tiny">${esc(sl.nota)}</span>`:""}</div>
      ${sug?`<p class="small ${sug.up?'up':sug.down?'down':'muted'}">${esc(sug.txt)}</p>`:`<p class="tiny">Primeira vez: escolha uma carga que deixe ${sl.rir||"1–2"} rep na reserva.</p>`}
      ${fl.map(f=>`<p class="tiny" style="color:#e2b26b">⚠ ${f.k}: ${esc(f.t)}</p>`).join("")}${susp?'<p class="small" style="color:#e07a6a">Suspenso enquanto o cotovelo doer. Pule.</p>':''}
      <div class="set-row" style="margin-top:6px"><span></span><span class="tiny" style="text-align:center">kg</span><span class="tiny" style="text-align:center">reps</span><span class="tiny" style="text-align:center">RIR</span><span></span></div>${sets}</div>`; }).join("");
  const iso=(s.isometria||[]).map(it=>{const e=EX[it.ex]; return `<div class="item" onclick="go('exercicio',{id:'${e.id}',back:'sessao',s:'${p.s}'})"><div class="n">⏳</div><div class="t"><b>${esc(e.nome)}</b><span>${it.sets} × ${it.tempo}${suspenso(e)?' · suspensa':''}</span></div></div>`;}).join("");
  return `<div class="row" style="margin-top:8px"><button class="btn sm ghost" onclick="go('treino')">‹ Sessões</button></div>
  <h1>${esc(s.nome)}</h1>
  <div class="card sub" id="timerCard"><div class="timer" id="timerVal">00:00</div><div class="grid3"><button class="btn sm sec" onclick="startTimer(90)">90 s</button><button class="btn sm sec" onclick="startTimer(120)">2 min</button><button class="btn sm sec" onclick="startTimer(180)">3 min</button></div></div>
  ${slots}
  ${iso?`<h3>Isometrias (2 por sessão, 30–50% da força)</h3><div class="list">${iso}</div>`:""}
  ${s.cardio?`<div class="card sub"><b>Cardio</b><p class="small">${esc(s.cardio)}</p></div>`:""}
  <div class="card"><div class="grid2"><div><label>BJJ no mesmo dia?</label><select id="lgBjj"><option value="0">Não</option><option value="1">Sim</option></select></div><div><label>Duração (min)</label><input id="lgDur" type="number" placeholder="60"></div></div><div class="grid2"><div><label>Dor cotovelo pós (0–10)</label><input id="lgCot" type="number" value="0"></div><div><label>Dor joelho pós (0–10)</label><input id="lgJo" type="number" value="0"></div></div><label>Notas</label><input id="lgNotas" placeholder="Performance, ajuste para a próxima"></div>
  <button class="btn em" onclick="finalizaSessao('${p.s}')">Finalizar sessão</button>
  <p class="tiny" style="text-align:center">As séries marcadas são salvas; a rotação avança para a próxima sessão.</p>`; };
A.sessao=(p)=>{ document.querySelectorAll('#view input[data-ex]').forEach(inp=>inp.addEventListener('input',()=>saveDraft(p.s))); };
function saveDraft(sess){ const pr=programa(); const sets=[]; document.querySelectorAll('#view .set-row').forEach(r=>{ const ins=r.querySelectorAll('input[data-ex]'); if(!ins.length) return; const ex=ins[0].dataset.ex, set=+ins[0].dataset.set; const o={ex,set}; ins.forEach(i=>o[i.dataset.f]=num(i.value)); o.done=r.querySelector('.ck').classList.contains('done'); sets.push(o); }); S._draft={programa:pr.id,sessao:sess,sets}; save(); }
window.toggleSet=(btn,rest)=>{ btn.classList.toggle('done'); btn.classList.add('pop'); setTimeout(()=>btn.classList.remove('pop'),120); if(btn.classList.contains('done')){ startTimer(parseRest(rest)); if(navigator.vibrate) navigator.vibrate(20); } const s=location.hash.match(/s=(\w+)/); saveDraft(s?s[1]:""); };
window.finalizaSessao=(sess)=>{ saveDraft(sess); const d=S._draft; const done=d.sets.filter(x=>x.done&&(x.reps||x.peso)); if(!done.length){ if(!confirm("Nenhuma série marcada. Salvar mesmo assim?")) return; }
  const pr=programa(); const log={id:uid(),data:today(),programa:pr.id,sessao:sess,nome:pr.sessoes[sess].nome,sets:d.sets,bjj:lgBjj.value==="1",dur:num(lgDur.value),dorCot:num(lgCot.value),dorJo:num(lgJo.value),notas:lgNotas.value};
  S.logs.push(log);
  const porEx={}; done.forEach(x=>{ if(!porEx[x.ex]) porEx[x.ex]={peso:0,reps:0,n:0,minReps:99}; const a=porEx[x.ex]; a.n++; if((x.peso||0)>=a.peso){a.peso=x.peso||0;a.reps=x.reps||0;} a.minReps=Math.min(a.minReps,x.reps||0); });
  Object.entries(porEx).forEach(([ex,a])=>{ const sl=pr.sessoes[sess].slots.find(s=>resolveEx(s.ex).id===ex); const mx=sl?parseInt((sl.reps||"").replace(/\/.*$/,'').split(/[–-]/).pop()):null; S.pesos[ex]={peso:a.peso,reps:a.reps,allTop:mx?a.minReps>=mx:false,data:today()}; });
  delete S._draft; avancaRotacao(); save(); toast("Sessão salva"); go('progresso',{t:'historico'}); };

// ================= EXERCÍCIO =================
V.exercicio=(p)=>{ const e=EX[p.id]; if(!e) return V.treino({t:'bib'}); setTitle("Exercício"); const fl=flagsAtivas(e); const sug=S.pesos[e.id]; const hist=S.logs.flatMap(l=>l.sets.filter(s=>s.ex===e.id&&s.done&&s.peso).map(s=>({data:l.data,peso:s.peso,reps:s.reps}))).slice(-12);
  const subs=Object.entries(e.modo||{}).filter(([k,v])=>v&&v!==e.id&&EX[v]).map(([k,v])=>`<span class="chip" onclick="go('exercicio',{id:'${v}'})">${MODOS[k].split(' ')[0]}: ${esc(EX[v].nome)}</span>`).join("");
  const back=p.back==="sessao"?`go('sessao',{s:'${p.s}'})`:"history.back()";
  return `<div class="row" style="margin-top:8px"><button class="btn sm ghost" onclick="${back}">‹ Voltar</button><span class="chip">${esc(e.grupo)}</span></div>
  <h1 style="font-size:24px">${esc(e.nome)}</h1><p class="muted small">${esc(e.sub)} · ${esc(e.padrao)}</p>
  ${e.video?ytEmbed(e.video):`<div class="card sub small">Sem vídeo escolhido ainda. <a href="https://www.youtube.com/results?search_query=${encodeURIComponent(e.nome+' execução')}" target="_blank">Buscar no YouTube ›</a></div>`}
  ${e.videoAlt?`<p class="tiny"><a href="${e.videoAlt}" target="_blank">Vídeo alternativo (completo) ›</a></p>`:""}
  ${fl.map(f=>`<div class="alert" style="margin:8px 0">⚠ ${f.k}: ${esc(f.t)}</div>`).join("")}
  <div class="card"><b>Pegada</b><p class="small">${esc(e.pegada)}</p><b>Posição</b><p class="small">${esc(e.posicao)}</p><b>Execução</b><p class="small">${esc(e.execucao)}</p></div>
  <div class="grid2"><div class="card"><b>Cues</b><ul class="small">${(e.cues||[]).map(c=>`<li>${esc(c)}</li>`).join("")}</ul></div><div class="card"><b>Erros comuns</b><ul class="small">${(e.erros||[]).map(c=>`<li>${esc(c)}</li>`).join("")}</ul></div></div>
  <div class="card"><b>Por que está aqui (mecânica)</b><p class="small">${esc(e.mecanica)}</p></div>
  ${subs?`<h3>Substitutos por modo</h3><div class="row wrap">${subs}</div>`:""}
  ${sug?`<h3>Seu registro</h3><div class="card"><div class="row"><span>Última carga</span><b class="mono">${sug.peso} kg × ${sug.reps}</b></div>${hist.length>1?`<div class="canvas-wrap" style="height:160px"><canvas id="exChart"></canvas></div>`:""}</div>`:""}`; };
A.exercicio=(p)=>{ const c=document.getElementById('exChart'); if(!c||!window.Chart) return; const e=EX[p.id]; const hist=S.logs.flatMap(l=>l.sets.filter(s=>s.ex===e.id&&s.done&&s.peso).map(s=>({data:l.data,v:s.peso*(1+(s.reps||0)/30)}))); const by={}; hist.forEach(h=>{by[h.data]=Math.max(by[h.data]||0,h.v);}); const ks=Object.keys(by).sort().slice(-12); mkChart(c,'line',ks.map(fmtD),[{label:"1RM estimado (Epley)",data:ks.map(k=>Math.round(by[k])),borderColor:"#4a7fb5",tension:.3}]); };

// ================= ESPORTES =================
V.esportes=(p)=>{ setTitle("Esportes"); if(p.id) return V._esporte(p); const tab=p.t||"modos";
  const segs=`<div class="seg">${[["modos","Modos"],["cardio","Cardio"],["feminino","Feminino"]].map(([k,n])=>`<button class="${tab===k?'on':''}" onclick="go('esportes',{t:'${k}'})">${n}</button>`).join("")}</div>`;
  if(tab==="cardio") return `<h1>Cardio</h1>${segs}${V._cardio()}`;
  if(tab==="feminino") return `<h1>Treino feminino</h1>${segs}${V._feminino(p)}`;
  return `<h1>Modos de esporte</h1>${segs}<p class="muted small">Cada modo diz o que o esporte exige, o que a ciência sustenta, e como encaixar na semana sem roubar a musculação.</p><div class="list">${window.SPORTS.map(s=>`<div class="item" onclick="go('esportes',{id:'${s.id}'})"><div class="n" style="font-size:18px">${s.emoji}</div><div class="t"><b>${esc(s.nome)}</b><span>${esc(s.status)}</span></div><span class="arrow">›</span></div>`).join("")}</div>`; };
V._esporte=(p)=>{ const s=window.SPORTS.find(x=>x.id===p.id); if(!s) return V.esportes({}); setTitle(s.nome);
  return `<div class="row" style="margin-top:8px"><button class="btn sm ghost" onclick="go('esportes')">‹ Esportes</button><span class="chip">${esc(s.status)}</span></div><h1>${s.emoji} ${esc(s.nome)}</h1>
  <div class="card"><p class="small">${esc(s.resumo)}</p><p class="tiny">Fonte: ${esc(s.fonte)}</p></div>
  ${s.estacoes?`<h3>As 8 estações (ordem fixa)</h3><div class="card"><div class="tablewrap"><table><tr><th>#</th><th>Estação</th><th>Dose</th><th>Open masc.</th></tr>${s.estacoes.map(e=>`<tr><td>${e.n}</td><td>${esc(e.nome)}</td><td>${esc(e.dose)}</td><td>${esc(e.open)}</td></tr>`).join("")}</table></div><p class="tiny">Entre cada estação, 1 km de corrida. Pesos oficiais mudam por divisão.</p></div>`:""}
  <h3>Demandas e como treinar</h3><div class="card"><div class="tablewrap"><table><tr><th>Qualidade</th><th>Onde aparece</th><th>Treino</th></tr>${s.demandas.map(d=>`<tr><td><b>${esc(d.q)}</b></td><td class="small">${esc(d.onde)}</td><td class="small">${esc(d.treino)}</td></tr>`).join("")}</table></div></div>
  ${s.semana?`<div class="card"><b>Semana</b><p class="small">${esc(s.semana)}</p></div>`:""}
  ${(s.blocos||[]).map(b=>`<div class="card"><b>${esc(b.nome)}</b><ul class="small">${b.itens.map(i=>`<li>${esc(i)}</li>`).join("")}</ul>${b.progressao?`<p class="tiny">Progressão: ${esc(b.progressao)}</p>`:""}</div>`).join("")}
  ${s.programa?`<h3>${esc(s.programa.nome)}</h3>${s.programa.fases.map(f=>`<details><summary>${esc(f.fase)}</summary>${f.obj?`<p class="small muted">${esc(f.obj)}</p>`:""}<ul class="small">${f.sessao.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>${f.progressao?`<p class="tiny">${esc(f.progressao)}</p>`:""}</details>`).join("")}`:""}
  <h3>Regras</h3><div class="card"><ul class="small">${s.regras.map(r=>`<li>${esc(r)}</li>`).join("")}</ul></div>
  ${s.link?`<p class="tiny">${esc(s.link)}</p>`:""}
  <div class="grid2"><button class="btn sec" onclick="sheet(V._logCardio('${s.id==='bjj'?'':s.id==='hyrox'?'Hyrox leve':s.id==='corrida'?'Corrida':s.nome}'))">Registrar sessão</button>${s.id==='hyrox'?`<button class="btn sec" onclick="go('treino',{t:'bib',g:'Hyrox'})">Estações na biblioteca</button>`:s.id==='bjj'?`<button class="btn sec" onclick="sheet(V._logBjj())">Registrar BJJ</button>`:`<button class="btn sec" onclick="go('esportes',{t:'cardio'})">Sessões de cardio</button>`}</div>`; };
V._cardio=()=>{ const c=window.CARDIO; return `<div class="card"><b>Zonas (referência inicial)</b><div class="tablewrap"><table><tr><th>Zona</th><th>FC</th><th>Sensação</th><th>Esteira</th></tr>${c.zonas.map(z=>`<tr><td><b>${z.z}</b></td><td class="mono">${z.fc}</td><td class="small">${z.rpe}</td><td class="small">${z.vel}</td></tr>`).join("")}</table></div><p class="tiny">${esc(c.nota)}</p></div>
  ${c.sessoes.map(s=>`<details><summary>${esc(s.nome)} <span class="tiny">${s.dur}</span></summary><ol class="small">${s.passos.map(x=>`<li>${esc(x)}</li>`).join("")}</ol>${s.progressao?`<p class="small"><b>Progressão:</b></p><ul class="small">${s.progressao.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`:""}${s.nota?`<p class="tiny">${esc(s.nota)}</p>`:""}<button class="btn sm sec" onclick="sheet(V._logCardio('${/Z2|base/.test(s.nome)?'Z2 base':/interval/.test(s.nome)?'Esteira intervalado':'Corrida'}'))">Registrar</button></details>`).join("")}
  <div class="card"><b>Regras</b><ul class="small">${c.regras.map(r=>`<li>${esc(r)}</li>`).join("")}</ul></div>`; };
V._feminino=(p)=>{ const f=window.FEMININO; const pg=p.pg; if(pg){ const prg=f.programas.find(x=>x.id===pg); return `<button class="btn sm ghost" onclick="go('esportes',{t:'feminino'})">‹ Feminino</button><h2>${esc(prg.nome)}</h2><p class="tiny">${esc(prg.origem)} · ${esc(prg.semana)}</p>${prg.sessoes.map(s=>`<div class="card"><b>${esc(s.nome)}</b><div class="seg"><button class="on" onclick="togFem(this,'n')">Normal</button><button onclick="togFem(this,'r')">Rápida</button></div><div class="tablewrap fem-n"><table>${s.normal.map(([a,b])=>`<tr><td>${esc(a)}</td><td class="num mono">${b}</td></tr>`).join("")}</table></div><div class="tablewrap fem-r hidden"><table>${s.rapida.map(([a,b])=>`<tr><td>${esc(a)}</td><td class="num mono">${b}</td></tr>`).join("")}</table></div></div>`).join("")}<div class="card"><b>Regras</b><ul class="small">${prg.regras.map(r=>`<li>${esc(r)}</li>`).join("")}</ul></div>`; }
  return `<p class="muted small">Pasta da Stefânia e princípios do treino feminino. Os dados corporais dela ficam só no perfil dela, não no app.</p><div class="list">${f.programas.map(x=>`<div class="item" onclick="go('esportes',{t:'feminino',pg:'${x.id}'})"><div class="n">♀</div><div class="t"><b>${esc(x.nome)}</b><span>${esc(x.semana)}</span></div><span class="arrow">›</span></div>`).join("")}</div><h3>Princípios</h3>${f.principios.map(x=>`<details><summary>${esc(x.t)}</summary><p class="small">${esc(x.d)}</p></details>`).join("")}`; };
window.togFem=(b,k)=>{ const card=b.closest('.card'); card.querySelectorAll('.seg button').forEach(x=>x.classList.remove('on')); b.classList.add('on'); card.querySelector('.fem-n').classList.toggle('hidden',k!=='n'); card.querySelector('.fem-r').classList.toggle('hidden',k!=='r'); };

// ================= PROGRESSO =================
V.progresso=(p)=>{ setTitle("Progresso"); const tab=p.t||"painel";
  const segs=`<div class="seg" style="overflow:auto">${[["painel","Painel"],["checkin","Check-in"],["historico","Histórico"],["exames","Exames"],["medalhas","Medalhas"]].map(([k,n])=>`<button class="${tab===k?'on':''}" onclick="go('progresso',{t:'${k}'})">${n}</button>`).join("")}</div>`;
  if(tab==="checkin") return `<h1>Check-in semanal</h1>${segs}${V._checkin()}`;
  if(tab==="historico") return `<h1>Histórico</h1>${segs}${V._historico()}`;
  if(tab==="exames") return `<h1>Exames e relógio</h1>${segs}${V._exames()}`;
  if(tab==="medalhas") return `<h1>Medalhas</h1>${segs}${V._medalhas()}`;
  const cks=S.checkins; const last=cks[cks.length-1]; const prev=cks[cks.length-2]; const d=(k)=>last&&prev&&last[k]!=null&&prev[k]!=null?last[k]-prev[k]:null;
  const kpi=(l,v,dd,un,inv)=>`<div class="kpi"><div class="l">${l}</div><div class="v">${v??"—"}<span class="small muted"> ${un}</span></div>${dd!=null?`<div class="d ${(inv?dd<=0:dd>=0)?'up':'down'}">${dd>0?'+':''}${Math.round(dd*10)/10} vs anterior</div>`:""}</div>`;
  return `<h1>Painel</h1>${segs}<div class="row" style="margin-bottom:6px"><button class="btn sm sec" onclick="go('calendario')">▦ Calendário mensal</button><button class="btn sm sec" onclick="go('nutricao',{t:'peso'})">⚖ Pesagens</button></div>
  <div class="grid2">${kpi("Peso",last?.peso,d('peso'),"kg",true)}${kpi("Cintura",last?.cintura,d('cintura'),"cm",true)}${kpi("Sono",last?.sono,d('sono'),"h")}${kpi("Passos",last?.passos,d('passos'),"/dia")}</div>
  ${cks.length>1?`<div class="card"><b>Peso e cintura</b><div class="canvas-wrap"><canvas id="chPeso"></canvas></div></div>`:`<div class="card sub small">Faça 2 check-ins para ver as curvas de peso e cintura.</div>`}
  <div class="card"><b>Sessões por semana (últimas 8)</b><div class="canvas-wrap"><canvas id="chSessoes"></canvas></div></div>
  <div class="card"><b>Volume semanal por grupo</b><div class="canvas-wrap"><canvas id="chVol"></canvas></div><p class="tiny">Barras = séries desta semana (diretas + 0,5 indiretas). Linha = alvo máximo.</p></div>
  <div class="card"><b>Cardio por tipo (minutos, 4 semanas)</b><div class="canvas-wrap"><canvas id="chCardio"></canvas></div></div>
  <div class="card"><b>Dor articular (0–10, últimas sessões)</b><div class="canvas-wrap" style="height:160px"><canvas id="chDor"></canvas></div></div>
  <h3>Recordes (1RM estimado, Epley)</h3><div class="card"><div class="tablewrap"><table><tr><th>Exercício</th><th class="num">Carga</th><th class="num">Reps</th><th class="num">1RM est.</th><th>Data</th></tr>${Object.entries(S.pesos).sort((a,b)=>b[1].peso-a[1].peso).slice(0,12).map(([k,v])=>`<tr><td class="small">${esc(EX[k]?.nome||k)}</td><td class="num mono">${v.peso}</td><td class="num mono">${v.reps}</td><td class="num mono">${Math.round(v.peso*(1+v.reps/30))}</td><td class="small">${fmtD(v.data)}</td></tr>`).join("")||`<tr><td colspan="5" class="muted small">Nenhuma sessão salva ainda.</td></tr>`}</table></div></div>`; };
A.progresso=(p)=>{ if(!window.Chart) return; const tab=p.t||"painel"; if(tab!=="painel") return;
  const cks=S.checkins; const c1=document.getElementById('chPeso'); if(c1&&cks.length>1){ const ks=cks.slice(-16); mkChart(c1,'line',ks.map(x=>fmtD(x.data)),[{label:"Peso kg",data:ks.map(x=>x.peso),borderColor:"#4a7fb5",tension:.3,yAxisID:'y'},{label:"Cintura cm",data:ks.map(x=>x.cintura),borderColor:"#c9a24a",tension:.3,yAxisID:'y1'}],{y1:{position:'right',grid:{display:false}}}); }
  const semanas=[]; for(let i=7;i>=0;i--){ const x=new Date(); x.setDate(x.getDate()-((x.getDay()+6)%7)-7*i); semanas.push(x.toISOString().slice(0,10)); }
  const inSem=(d,s)=>{const e=new Date(s); e.setDate(e.getDate()+7); return d>=s&&d<e.toISOString().slice(0,10);};
  mkChart(document.getElementById('chSessoes'),'bar',semanas.map(fmtD),[{label:"Musculação",data:semanas.map(s=>S.logs.filter(l=>inSem(l.data,s)).length),backgroundColor:"#315E8A"},{label:"BJJ",data:semanas.map(s=>S.bjj.filter(l=>inSem(l.data,s)).length),backgroundColor:"#7A513A"},{label:"Cardio",data:semanas.map(s=>S.cardio.filter(l=>inSem(l.data,s)).length),backgroundColor:"#5c7a3f"}],{x:{stacked:true},y:{stacked:true}});
  const vol=volumeSemana(); const gs=Object.keys(ALVO); mkChart(document.getElementById('chVol'),'bar',gs,[{label:"Séries",data:gs.map(g=>Math.round((vol[g]||0)*10)/10),backgroundColor:gs.map(g=>{const v=vol[g]||0;const[a,b]=ALVO[g];return v>=a&&v<=b?cssv('--ok'):v>b?cssv('--warn'):cssv('--bone');})},{label:"Alvo máx",data:gs.map(g=>ALVO[g][1]),type:'line',borderColor:"#9C9A93",pointRadius:0,borderDash:[4,4]}]);
  const lim=new Date(); lim.setDate(lim.getDate()-28); const l=lim.toISOString().slice(0,10); const tipos={}; S.cardio.filter(c=>c.data>=l).forEach(c=>{tipos[c.tipo]=(tipos[c.tipo]||0)+(c.min||0);}); const tk=Object.keys(tipos); mkChart(document.getElementById('chCardio'),'bar',tk.length?tk:["—"],[{label:"min",data:tk.length?tk.map(k=>tipos[k]):[0],backgroundColor:"#4a7fb5"}]);
  const dl=[...S.logs.map(x=>({d:x.data,c:x.dorCot,j:x.dorJo})),...S.bjj.map(x=>({d:x.data,c:x.dorCot,j:x.dorJo}))].sort((a,b)=>a.d.localeCompare(b.d)).slice(-20); mkChart(document.getElementById('chDor'),'line',dl.map(x=>fmtD(x.d)),[{label:"Cotovelo",data:dl.map(x=>x.c),borderColor:cssv('--stop'),tension:.3},{label:"Joelho",data:dl.map(x=>x.j),borderColor:cssv('--warn'),tension:.3}],{y:{min:0,max:10}}); };
function cssv(n){ return getComputedStyle(document.documentElement).getPropertyValue(n).trim(); }
function mkChart(c,type,labels,datasets,scales={}){ if(!c) return; Chart.defaults.color=cssv('--tx2'); Chart.defaults.borderColor=cssv('--line'); datasets.forEach(d=>{ if(d.borderColor==='#4a7fb5') d.borderColor=cssv('--tx'); if(d.backgroundColor==='#4a7fb5') d.backgroundColor=cssv('--bone'); if(d.backgroundColor==='#315E8A') d.backgroundColor=cssv('--tx'); if(d.backgroundColor==='#7A513A') d.backgroundColor=cssv('--bone'); if(d.backgroundColor==='#5c7a3f') d.backgroundColor=cssv('--ember'); if(d.borderColor==='#c9a24a') d.borderColor=cssv('--ember'); if(d.borderColor==='#9C9A93') d.borderColor=cssv('--ember'); }); Chart.defaults.font.family=getComputedStyle(document.body).fontFamily; new Chart(c,{type,data:{labels,datasets},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:datasets.length>1,labels:{boxWidth:10}}},scales:Object.assign({y:{beginAtZero:true}},scales)}}); }
V._checkin=()=>{ const last=S.checkins[S.checkins.length-1]||{}; const rows=S.checkins.slice(-12).reverse();
  return `<div class="card"><p class="tiny">Mesma condição sempre: manhã, em jejum, após o banheiro. Peso = média de 7 dias se tiver. Cintura no mesmo ponto anatômico.</p>
  <label>Data</label><input id="ckData" type="date" value="${today()}"><div class="grid2"><div><label>Peso (kg)</label><input id="ckPeso" type="number" step="0.1" placeholder="${last.peso||''}"></div><div><label>Cintura (cm)</label><input id="ckCint" type="number" step="0.5" placeholder="${last.cintura||''}"></div></div>
  <div class="grid3"><div><label>Peito cm</label><input id="ckPeito" type="number" step="0.5"></div><div><label>Braço cm</label><input id="ckBraco" type="number" step="0.5"></div><div><label>Coxa cm</label><input id="ckCoxa" type="number" step="0.5"></div></div>
  <div class="grid3"><div><label>Sono (h/noite)</label><input id="ckSono" type="number" step="0.1"></div><div><label>Passos/dia</label><input id="ckPassos" type="number"></div><div><label>Fadiga 0–10</label><input id="ckFad" type="number"></div></div>
  <div class="grid3"><div><label>FC repouso</label><input id="ckFcr" type="number"></div><div><label>HRV (ms)</label><input id="ckHrv" type="number"></div><div><label>Energia 0–10</label><input id="ckEne" type="number"></div></div>
  <label>Aderência alimentar (%)</label><input id="ckAder" type="number" placeholder="80"><label>Leitura da semana (o que aumentou / drenou a potência; a única variável a ajustar)</label><textarea id="ckNotas" rows="3"></textarea>
  <div style="margin-top:12px"><button class="btn" onclick="salvaCheckin()">Salvar check-in</button></div></div>
  ${rows.length?`<div class="card"><b>Últimos</b><div class="tablewrap"><table><tr><th>Data</th><th class="num">Peso</th><th class="num">Cint.</th><th class="num">Sono</th><th class="num">Passos</th><th class="num">Fad.</th></tr>${rows.map(r=>`<tr><td>${fmtD(r.data)}</td><td class="num mono">${r.peso??"—"}</td><td class="num mono">${r.cintura??"—"}</td><td class="num mono">${r.sono??"—"}</td><td class="num mono">${r.passos??"—"}</td><td class="num mono">${r.fadiga??"—"}</td></tr>`).join("")}</table></div></div>`:""}`; };
window.salvaCheckin=()=>{ const ck={id:uid(),data:ckData.value,peso:num(ckPeso.value),cintura:num(ckCint.value),peito:num(ckPeito.value),braco:num(ckBraco.value),coxa:num(ckCoxa.value),sono:num(ckSono.value),passos:num(ckPassos.value),fadiga:num(ckFad.value),fcrep:num(ckFcr.value),hrv:num(ckHrv.value),energia:num(ckEne.value),ader:num(ckAder.value),notas:ckNotas.value}; const ex=S.checkins.find(x=>x.data===ck.data); if(ex) Object.keys(ck).forEach(k=>{if(ck[k]!=null&&ck[k]!==""&&k!=='id') ex[k]=ck[k];}); else S.checkins.push(ck); S.checkins.sort((a,b)=>a.data.localeCompare(b.data)); if(ck.peso) S.perfil.peso=ck.peso; save(); toast("Check-in salvo"); go('progresso'); };
V._historico=()=>{ const all=[...S.logs.map(l=>({d:l.data,t:"musc",o:l})),...S.bjj.map(b=>({d:b.data,t:"bjj",o:b})),...S.cardio.map(c=>({d:c.data,t:"cardio",o:c}))].sort((a,b)=>b.d.localeCompare(a.d)).slice(0,60);
  return `<div class="list">${all.map(x=>{ if(x.t==="musc"){ const done=x.o.sets.filter(s=>s.done); const ton=done.reduce((a,s)=>a+(s.peso||0)*(s.reps||0),0); return `<div class="item" onclick="sheet(V._logDetail('${x.o.id}'))"><div class="n">🏋️</div><div class="t"><b>${esc(x.o.nome)}</b><span>${fmtDL(x.d)} · ${done.length} séries · ${Math.round(ton)} kg tonelagem${x.o.bjj?' · +BJJ':''}</span></div><span class="arrow">›</span></div>`; }
    if(x.t==="bjj") return `<div class="item"><div class="n">🥋</div><div class="t"><b>BJJ ${esc(x.o.tipo)}</b><span>${fmtDL(x.d)} · ${x.o.min||"—"} min · RPE ${x.o.rpe||"—"}${x.o.notas?' · '+esc(x.o.notas):''}</span></div><button class="btn sm ghost" onclick="delItem('bjj','${x.o.id}')">✕</button></div>`;
    return `<div class="item"><div class="n">❤️</div><div class="t"><b>${esc(x.o.tipo)}</b><span>${fmtDL(x.d)} · ${x.o.min||"—"} min${x.o.fc?' · '+x.o.fc+' bpm':''}${x.o.dist?' · '+x.o.dist+' km':''}</span></div><button class="btn sm ghost" onclick="delItem('cardio','${x.o.id}')">✕</button></div>`; }).join("")||'<p class="muted">Nada registrado ainda.</p>'}</div>`; };
V._logDetail=(id)=>{ const l=S.logs.find(x=>x.id===id); if(!l) return ""; const by={}; l.sets.filter(s=>s.done).forEach(s=>{(by[s.ex]=by[s.ex]||[]).push(s);}); return `<h2>${esc(l.nome)} · ${fmtDL(l.data)}</h2>${Object.entries(by).map(([ex,ss])=>`<div class="card sub"><b>${esc(EX[ex]?.nome||ex)}</b><p class="small mono">${ss.map(s=>`${s.peso||"—"}×${s.reps||"—"}${s.rir!=null?" @"+s.rir:""}`).join("  ·  ")}</p></div>`).join("")}${l.notas?`<p class="small">${esc(l.notas)}</p>`:""}<p class="tiny">Dor pós: cotovelo ${l.dorCot??"—"} · joelho ${l.dorJo??"—"}</p><button class="btn danger sm" onclick="delItem('logs','${l.id}');closeSheet()">Apagar sessão</button>`; };
window.delItem=(k,id)=>{ if(!confirm("Apagar este registro?")) return; S[k]=S[k].filter(x=>x.id!==id); save(); route(); };
V._exames=()=>{ const ex=S.exames.slice().sort((a,b)=>b.data.localeCompare(a.data)); const marc=[...new Set(S.exames.map(e=>e.marcador))];
  return `<div class="card"><b>Relógio e balança</b><p class="small">Num site estático não existe integração direta com Apple Health, Garmin ou Whoop (isso exige app nativo ou um serviço pago com servidor). O caminho gratuito é exportar e importar:</p><ol class="small"><li>iPhone: app Atalhos → atalho que lê Saúde (peso, passos, sono, FC repouso, HRV) e salva CSV; ou apps como Health Auto Export (gratuito na versão básica).</li><li>Garmin/Strava/Zepp: exportar CSV no site.</li><li>Importe aqui. Colunas aceitas: <code>data,peso,cintura,passos,sono,fc_repouso,hrv</code> (data AAAA-MM-DD).</li></ol><input type="file" accept=".csv" onchange="importCSV(this.files[0])"></div>
  <div class="card"><b>Registrar exame</b><p class="tiny">Fica só neste aparelho. Faça backup em Mais → Exportar. Nunca suba este arquivo para o repositório.</p><div class="grid2"><div><label>Data</label><input id="exData" type="date" value="${today()}"></div><div><label>Marcador</label><input id="exMarc" list="marcs" placeholder="HDL, LDL, HbA1c, PCR-us, Hematócrito, PA…"><datalist id="marcs">${["HDL","LDL","Colesterol total","Triglicerídeos","HbA1c","Glicemia jejum","PCR-us","Hematócrito","Hemoglobina","Ferritina","Creatinina","TGO","TGP","Vitamina D","Testosterona total","Pressão arterial","Peso (bioimpedância)","% gordura (bioimpedância)"].map(m=>`<option value="${m}">`).join("")}</datalist></div></div><div class="grid3"><div><label>Valor</label><input id="exVal" placeholder="39"></div><div><label>Unidade</label><input id="exUn" placeholder="mg/dL"></div><div><label>Referência</label><input id="exRef" placeholder=">40"></div></div><label>Laboratório / fonte</label><input id="exFonte"><div style="margin-top:12px"><button class="btn" onclick="salvaExame()">Salvar exame</button></div></div>
  ${marc.length?`<div class="card"><b>Evolução</b><select id="exSel" onchange="drawExame(this.value)">${marc.map(m=>`<option>${esc(m)}</option>`).join("")}</select><div class="canvas-wrap" style="height:180px;margin-top:8px"><canvas id="chExame"></canvas></div></div>`:""}
  ${ex.length?`<div class="card"><div class="tablewrap"><table><tr><th>Data</th><th>Marcador</th><th class="num">Valor</th><th>Ref.</th><th></th></tr>${ex.map(e=>`<tr><td>${fmtD(e.data)}</td><td>${esc(e.marcador)}</td><td class="num mono">${esc(e.valor)} ${esc(e.unidade||"")}</td><td class="small">${esc(e.ref||"")}</td><td><button class="btn sm ghost" onclick="delItem('exames','${e.id}')">✕</button></td></tr>`).join("")}</table></div></div>`:""}
  <p class="tiny">O app organiza dados e perguntas para a consulta. Não interpreta exame nem ajusta medicação.</p>`; };
window.salvaExame=()=>{ if(!exMarc.value) return toast("Informe o marcador"); S.exames.push({id:uid(),data:exData.value,marcador:exMarc.value.trim(),valor:exVal.value,unidade:exUn.value,ref:exRef.value,fonte:exFonte.value}); save(); toast("Exame salvo"); route(); };
window.drawExame=(m)=>{ const c=document.getElementById('chExame'); if(!c) return; const ds=S.exames.filter(e=>e.marcador===m).sort((a,b)=>a.data.localeCompare(b.data)); c.replaceWith(c.cloneNode()); mkChart(document.getElementById('chExame'),'line',ds.map(e=>fmtD(e.data)),[{label:m,data:ds.map(e=>num(e.valor)),borderColor:"#4a7fb5",tension:.3}],{y:{beginAtZero:false}}); };
V._medalhas=()=>{ const ms=medalhas(); const cats=[...new Set(ms.map(m=>m.cat))]; const total=ms.reduce((a,m)=>a+m.tier,0);
  return `<div class="card hero"><div class="row"><div><b>${total} níveis conquistados</b><div class="tiny">de ${ms.length*3} possíveis · ${streakSemanas()} semanas seguidas</div></div><span style="font-size:32px">${total>=ms.length*2?"🏆":total>=ms.length?"🥈":"🥉"}</span></div></div>
  ${cats.map(c=>`<h3>${c}</h3><div class="grid3">${ms.filter(m=>m.cat===c).map(m=>`<div class="medal ${m.tier?'won':''} t${m.tier}"><div class="ico">${m.ico}</div><b>${esc(m.nome)}</b><span>${TIER[m.tier]}</span><span class="mono">${m.v} ${m.un}</span>${m.prox?`<div class="bar" style="width:100%"><i style="width:${Math.min(100,m.v/m.prox*100)}%"></i></div><span>próx. ${m.prox}</span>`:'<span>máximo</span>'}</div>`).join("")}</div>`).join("")}
  <p class="tiny">Bronze / Prata / Ouro por esporte e por consistência. As medalhas de composição medem queda em relação ao máximo que você registrou, nunca um número absoluto.</p>`; };

// ================= MAIS =================
V.mais=(p)=>{ setTitle("Mais"); const tab=p.t||"menu";
  if(tab==="perfil") return `<button class="btn sm ghost" onclick="go('mais')">‹ Mais</button><h1>Perfil</h1>${V._perfil()}`;
  if(tab==="nutri") return `<button class="btn sm ghost" onclick="go('mais')">‹ Mais</button><h1>Nutrição</h1>${V._nutri()}`;
  if(tab==="ciencia") return `<button class="btn sm ghost" onclick="go('mais')">‹ Mais</button><h1>Ciência</h1>${V._ciencia()}`;
  if(tab==="dados") return `<button class="btn sm ghost" onclick="go('mais')">‹ Mais</button><h1>Dados</h1>${V._dados()}`;
  return `<h1>Mais</h1><div class="list">${[["esportes","◎","Esportes","BJJ, Hyrox, corrida, boxe, futebol, natação, feminino","r"],["calendario","▦","Calendário","Mês com treinos, BJJ, cardio e planejado","r"],["gerador","✦","Montar programa","O Método DOSE monta pelo seu perfil","r"],["tutorial","?","Tutorial","Como usar e rotina sugerida","r"],["perfil","👤","Perfil e modo","Dados, equipamento, tema, flags de dor"],["ciencia","📚","Ciência","As referências por trás de cada regra"],["dados","💾","Dados","Backup, importar, apagar"]].map(([k,i,n,d,r])=>`<div class="item" onclick="${r?`go('${k}')`:`go('mais',{t:'${k}'})`}"><div class="n" style="font-size:18px">${i}</div><div class="t"><b>${n}</b><span>${d}</span></div><span class="arrow">›</span></div>`).join("")}</div><p class="serif" style="margin-top:24px">O melhor programa é o que você <i>consegue</i> sustentar.</p><p class="tiny">DOSE · v1.1 · 2026-10-25 · A dose certa. Dados ficam neste aparelho. Programa vigente: PPL 2.0.</p>`; };
V._perfil=()=>{ const p=S.perfil; return `<div class="card"><label>Nome</label><input id="pfNome" value="${esc(p.nome)}"><div class="grid3"><div><label>Sexo</label><select id="pfSexo"><option value="m" ${p.sexo==='m'?'selected':''}>M</option><option value="f" ${p.sexo==='f'?'selected':''}>F</option></select></div><div><label>Idade</label><input id="pfIdade" type="number" value="${p.idade??''}"></div><div><label>Altura cm</label><input id="pfAlt" type="number" value="${p.altura??''}"></div></div><div class="grid2"><div><label>Peso kg</label><input id="pfPeso" type="number" step="0.1" value="${p.peso??''}"></div><div><label>% gordura (opcional)</label><input id="pfBf" type="number" step="0.5" value="${p.bf??''}"></div></div>
  <label>Nível de atividade</label><select id="pfAt">${window.NUTRI.atividade.map(a=>`<option value="${a.k}" ${p.atividade===a.k?'selected':''}>${a.n}</option>`).join("")}</select><label>Objetivo</label><select id="pfOb">${window.NUTRI.objetivos.map(a=>`<option value="${a.k}" ${p.objetivo===a.k?'selected':''}>${a.n}</option>`).join("")}</select>
  <label>Modo de equipamento</label><select id="pfModo">${Object.entries(MODOS).map(([k,n])=>`<option value="${k}" ${p.modo===k?'selected':''}>${n}</option>`).join("")}</select>
  <label>Tema</label><select id="pfTema"><option value="dark" ${(p.tema||'dark')==='dark'?'selected':''}>Escuro (academia)</option><option value="light" ${p.tema==='light'?'selected':''}>Claro (rua)</option><option value="auto" ${p.tema==='auto'?'selected':''}>Seguir o sistema</option></select>
  <label>Programa</label><select id="pfProg"><option value="ppl2" ${p.programa==='ppl2'?'selected':''}>PPL 2.0</option><option value="predio" ${p.programa==='predio'?'selected':''}>Prédio A/B</option></select>
  <div class="grid2" style="margin-top:10px"><label class="row" style="margin:0"><span>Cotovelo sintomático</span><input type="checkbox" id="pfCot" ${p.cotovelo?'checked':''} style="width:auto"></label><label class="row" style="margin:0"><span>Joelho sintomático</span><input type="checkbox" id="pfJo" ${p.joelho?'checked':''} style="width:auto"></label></div>
  <div style="margin-top:14px"><button class="btn" onclick="salvaPerfil()">Salvar</button></div></div>
  <div class="card"><b>Protocolo vigente do coach/nutri (opcional)</b><p class="tiny">Prevalece sobre a calculadora. Fica só no aparelho.</p><div class="grid2"><div><label>kcal/dia</label><input id="pcK" type="number" value="${p.protocoloCoach.kcal??''}"></div><div><label>Proteína g</label><input id="pcP" type="number" value="${p.protocoloCoach.p??''}"></div></div><div class="grid2"><div><label>Carboidrato g</label><input id="pcC" type="number" value="${p.protocoloCoach.c??''}"></div><div><label>Gordura g</label><input id="pcG" type="number" value="${p.protocoloCoach.g??''}"></div></div><label>Fonte / data</label><input id="pcF" value="${esc(p.protocoloCoach.fonte)}"><div style="margin-top:12px"><button class="btn sec" onclick="salvaCoach()">Salvar protocolo</button></div></div>`; };
window.salvaPerfil=()=>{ const p=S.perfil; p.nome=pfNome.value; p.sexo=pfSexo.value; p.idade=num(pfIdade.value); p.altura=num(pfAlt.value); p.peso=num(pfPeso.value); p.bf=num(pfBf.value); p.atividade=pfAt.value; p.objetivo=pfOb.value; p.modo=pfModo.value; p.programa=pfProg.value; p.cotovelo=pfCot.checked; p.joelho=pfJo.checked; p.tema=pfTema.value; save(); toast("Perfil salvo"); route(); };
window.salvaCoach=()=>{ S.perfil.protocoloCoach={kcal:num(pcK.value),p:num(pcP.value),c:num(pcC.value),g:num(pcG.value),fonte:pcF.value}; save(); toast("Protocolo salvo"); };
V._nutri=()=>{ const n=calcNutri(S.perfil); const pc=S.perfil.protocoloCoach; const N=window.NUTRI;
  return `${pc.kcal?`<div class="card hero"><b>Protocolo vigente (${esc(pc.fonte||"coach")})</b><div class="grid3" style="margin-top:8px"><div class="kpi"><div class="v">${pc.kcal}</div><div class="l">kcal</div></div><div class="kpi"><div class="v">${pc.p??"—"}</div><div class="l">prot g</div></div><div class="kpi"><div class="v">${pc.c??"—"}</div><div class="l">carb g</div></div></div><p class="tiny">${esc(N.precedencia)}</p></div>`:`<div class="card sub small">${esc(N.precedencia)} Cadastre o protocolo em Perfil.</div>`}
  ${!n?`<div class="card"><b>Preencha idade, altura e peso no Perfil</b><button class="btn sm sec" onclick="go('mais',{t:'perfil'})">Ir ao perfil</button></div>`:`
  <div class="card"><b>Calculadora conservadora</b><div class="tablewrap"><table>${n.eq.map(e=>`<tr><td class="small">${e.n}</td><td class="num mono">${Math.round(e.v)} kcal</td></tr>`).join("")}<tr><td><b>TMB usada (a menor)</b></td><td class="num mono"><b>${n.tmb}</b></td></tr><tr><td class="small">× fator conservador ${n.fator.fc} (padrão seria ${n.fator.f} → ${n.tdeePadrao})</td><td class="num mono">${n.tdee}</td></tr><tr><td><b>Alvo diário</b></td><td class="num mono"><b>${n.alvo} kcal</b></td></tr></table></div>
  <div class="grid3" style="margin-top:10px"><div class="kpi"><div class="v">${n.prot}<span class="small muted">g</span></div><div class="l">proteína · ${Math.round(n.prot*4/n.alvo*100)}%</div></div><div class="kpi"><div class="v">${n.carb}<span class="small muted">g</span></div><div class="l">carboidrato</div></div><div class="kpi"><div class="v">${n.gord}<span class="small muted">g</span></div><div class="l">gordura · ${Math.round(n.gord*9/n.alvo*100)}%</div></div></div>
  <p class="small" style="margin-top:10px">Ritmo esperado: <b>${n.perdaSem<0?"−":"+"}${Math.abs(n.perdaSem)} kg/semana</b> (${n.pctPerda}% do peso${n.pctPerda>1?" · acima de 1%, risco de perder massa magra":""}). Água ~${n.agua} L/dia.${n.ffm?` Massa magra estimada ${n.ffm} kg.`:" Informe % de gordura para usar equações por massa magra."}</p><div class="canvas-wrap" style="height:160px"><canvas id="chMacro"></canvas></div></div>`}
  <div class="card"><b>Regras</b><ul class="small">${N.regras.map(r=>`<li>${esc(r)}</li>`).join("")}</ul><p class="tiny">${esc(N.nota)}</p></div>
  <div class="card"><b>Trocas equivalentes (do protocolo em vigor)</b><p class="small"><b>Proteína:</b> carne/frango/peixe 1:1 · 5 claras + 2 g azeite · 20 g whey + 1 castanha · 20 g albumina + 1 castanha.<br><b>Carboidrato:</b> arroz, macarrão, cuscuz, batata-doce, aipim, batata, wrap/pão integral, aveia, tapioca, feijão, lentilha, grão-de-bico, pipoca sem óleo.<br><b>Gordura:</b> abacate, azeite, castanhas, pasta de amendoim, gema, chocolate 70%.</p></div>`; };
A.mais=(p)=>{ if(p.t==="nutri"){ const n=calcNutri(S.perfil); const c=document.getElementById('chMacro'); if(n&&c) mkChart(c,'bar',["Proteína","Carboidrato","Gordura"],[{label:"kcal",data:[n.prot*4,n.carb*4,n.gord*9],backgroundColor:[cssv('--tx'),cssv('--bone'),cssv('--ember')]}]); } };
V._ciencia=()=>`<p class="muted small">Cada regra do app aponta para a fonte. Status "verificado" = link e dado conferidos em 25/10/2026. O que o ChatGPT citou e não foi conferido está como "a confirmar".</p>${window.SCIENCE.map(r=>`<div class="ref"><b>${esc(r.t)}</b><p class="small">${esc(r.oque)}</p><p class="small"><b>No app:</b> ${esc(r.regra)}</p><p class="tiny">${esc(r.ref)} · <a href="${r.url}" target="_blank">fonte ›</a></p><div class="st">${esc(r.status)}</div></div>`).join("")}`;
V._dados=()=>`<div class="card"><b>Backup</b><p class="small">Tudo (sessões, check-ins, exames, perfil) está só neste navegador. Exporte com frequência; o arquivo é seu.</p><button class="btn sec" onclick="exportJSON()">Exportar backup (.json)</button><label>Restaurar backup</label><input type="file" accept=".json" onchange="importJSON(this.files[0])"></div><div class="card"><b>Importar CSV do relógio/balança</b><p class="tiny">Colunas: data,peso,cintura,passos,sono,fc_repouso,hrv</p><input type="file" accept=".csv" onchange="importCSV(this.files[0])"></div><div class="card"><b>Apagar tudo</b><button class="btn danger" onclick="if(confirm('Apagar todos os dados deste aparelho?')){localStorage.removeItem(DB_KEY);location.reload();}">Apagar dados</button></div>`;
